const { tokenize } = require('./parse.js');

function lcp(words) {
  if (!words.length) return '';
  let p = words[0];
  for (const w of words.slice(1)) {
    let i = 0;
    while (i < p.length && i < w.length && p[i] === w[i]) i++;
    p = p.slice(0, i);
  }
  return p;
}

